/* SIGNATURE LAYOUT STANDARD v4: 70% larger ink area with a one-line action caption. */
.signature{height:108px;font-size:16px;line-height:20px;text-align:center;white-space:normal;overflow:visible}
.action-signature-image{display:block;width:190px!important;height:64px!important;max-width:190px!important;max-height:64px!important;margin:0 auto 2px;object-fit:fill;transform:none}
.signature-placeholder{display:block;width:190px;height:64px;margin:0 auto 2px;border-bottom:1px solid #565656}
.signature-name,.signature-role{display:inline;overflow:visible;text-overflow:clip;white-space:nowrap}
.signature-role{margin-left:4px;font-size:14px;line-height:18px}
.sign_date{font-size:16px;line-height:20px;text-align:center;white-space:nowrap;border:0!important}
.sign_date_caption{margin-top:3px;font-size:14px;line-height:18px}
/* SIGNATURE LAYOUT STANDARD v5: artwork uses its native scale while preserving government form coordinates. */
.action-signature-image{transform:scale(1);transform-origin:center center;position:relative;z-index:2}
/* SIGNATURE LAYOUT STANDARD v7: center date values on the visible signature artwork. */
.cd-invoice .date-line{position:absolute!important;transform:translateY(3.8mm);z-index:1}
.cd-invoice .authorized-date,.cd-invoice .approved-date{transform:translateY(3.8mm);position:absolute;z-index:1}
.order-date-line,.authorized-date-line{transform:translateY(3.8mm);position:absolute;z-index:1}
.cd-print .signature-date,.cd-gr .signature-date{transform:translateY(3.8mm);z-index:1}
.cdq .signature-date{transform:translateY(3.8mm);z-index:1}
/* SIGNATURE LAYOUT STANDARD v8: center each action date on the visible signature. */
.cd-invoice .date-line{position:absolute!important;transform:translateY(9.5mm);z-index:1}
/* SIGNATURE LAYOUT STANDARD v10: use a direct top offset for wkhtmltopdf date alignment. */
.cd-invoice .date-line{position:absolute!important;top:4mm!important;transform:none!important;z-index:1}
/* SIGNATURE LAYOUT STANDARD v11: leave a readable gap before the employee caption. */
.cd-invoice .signature-caption{top:13mm!important}
.cd-invoice .signature-line{border:0!important;background:none!important}
.cd-invoice .authorized-date,.cd-invoice .approved-date{transform:translateY(5mm);position:absolute;z-index:1}
.order-date-line,.authorized-date-line{transform:translateY(5mm);position:absolute;z-index:1}
.cd-print .signature-date,.cd-gr .signature-date{transform:translateY(5mm);z-index:1}
.cdq .signature-date{transform:translateY(5mm);z-index:1}
