/* wkhtmltopdf does not lay out CSS grid reliably: use explicit coordinates. */
.cd-print .summary-section,.cd-gr .summary-section{position:relative!important;display:block!important;overflow:hidden!important}
.cd-so .summary-section>.remark-box{position:absolute!important;left:0!important;top:0!important;width:60.5%!important;height:100%!important}
.cd-so .summary-section>.totals-box{position:absolute!important;left:60.5%!important;right:0!important;top:0!important;width:39.5%!important;height:100%!important}
.cd-gr .summary-section>.remark-box{position:absolute!important;left:0!important;top:0!important;width:61%!important;height:100%!important}
.cd-gr .summary-section>.totals-box{position:absolute!important;left:61%!important;right:0!important;top:0!important;width:39%!important;height:100%!important}
.cd-print .totals-box .total-row,.cd-gr .totals-box .total-row{position:relative!important;display:block!important;flex:none!important;min-height:0!important;height:8.7mm!important}
.cd-so .totals-box .total-label,.cd-gr .totals-box .total-label{position:absolute!important;left:0!important;right:29.5mm!important;top:0!important;width:auto!important;height:100%!important}
.cd-so .totals-box .total-value{position:absolute!important;right:0!important;top:0!important;width:29.5mm!important;height:100%!important}
.cd-gr .totals-box .total-label{position:absolute!important;left:0!important;right:30mm!important;top:0!important;width:auto!important;height:100%!important}
.cd-gr .totals-box .total-value{position:absolute!important;right:0!important;top:0!important;width:30mm!important;height:100%!important}

.cd-print .signature-section,.cd-gr .signature-section{position:relative!important;display:block!important;overflow:hidden!important}
.cd-print .signature-block,.cd-gr .signature-block{position:absolute!important;top:0!important;width:33.333333%!important;height:100%!important;min-width:0!important;margin:0!important;padding-top:0!important}
.cd-print .signature-block:nth-child(1),.cd-gr .signature-block:nth-child(1){left:0!important}
.cd-print .signature-block:nth-child(2),.cd-gr .signature-block:nth-child(2){left:33.333333%!important}
.cd-print .signature-block:nth-child(3),.cd-gr .signature-block:nth-child(3){left:66.666666%!important}
.cd-print .signature-title,.cd-gr .signature-title{left:1mm!important;right:1mm!important;width:auto!important;white-space:nowrap!important;text-overflow:clip!important}

/* The quotation footer is positioned explicitly so it remains inside A4. */
.cdq .quotation-grid{display:block!important;flex:none!important;width:100%!important;height:98.64mm!important;min-height:98.64mm!important;max-height:98.64mm!important;overflow:hidden!important}
.cdq .product-body{display:block!important;flex:none!important;width:100%!important;height:51mm!important;min-height:51mm!important;max-height:51mm!important;overflow:hidden!important}
.cdq .words-row{display:block!important;flex:none!important;width:100%!important;height:5mm!important;min-height:5mm!important;max-height:5mm!important;padding:.35mm 2mm 0!important;font-size:3.75mm!important;line-height:4mm!important;overflow:hidden!important}
.cdq .quotation-footer{position:relative!important;display:block!important;flex:none!important;width:100%!important;height:27.5mm!important;min-height:27.5mm!important;max-height:27.5mm!important;overflow:hidden!important}
.cdq .quotation-footer>.bank-panel{position:absolute!important;left:0!important;top:0!important;width:100.9mm!important;height:100%!important}
.cdq .quotation-footer>.signature-panel{position:absolute!important;left:100.9mm!important;right:0!important;top:0!important;width:auto!important;height:100%!important}

/* PO reserves the final-page footer budget in Jinja. */
.cd-po-root .manual-page.last-page .preview-product-body{height:30mm!important;min-height:30mm!important;max-height:30mm!important}

/* The government form keeps its original coordinate system, but follows the same fallback rule. */
.o_report_withholding_tax_cert .action-signature-image{display:block!important;width:190px!important;height:64px!important;max-width:190px!important;max-height:64px!important;margin:0 auto 2px!important;object-fit:contain!important;transform:scale(1)!important;transform-origin:center center!important;border:0!important}
.o_report_withholding_tax_cert .signature-placeholder{display:block!important;width:190px!important;height:0!important;margin:0 auto 2px!important;border:0!important;border-bottom:1px solid #565656!important;background:none!important}

html:
{{ register_print(doc) }}
{% set print_actions = get_print_action_context(doc) %}

{% set copies = [
    '<b>ฉบับที่ 1</b> (สำหรับผู้ถูกหักภาษี ณ ที่จ่าย ใช้แนบพร้อมกับแบบแสดงรายการภาษี)',
    '<b>ฉบับที่ 2</b> (สำหรับผู้ถูกหักภาษี ณ ที่จ่าย เก็บไว้เป็นหลักฐาน)',
    '<b>ฉบับที่ 3</b> (สำหรับผู้หักภาษี ณ ที่จ่าย ใช้แนบแสดงรายการภาษี)',
    '<b>ฉบับที่ 4</b> (สำเนาติดเล่ม สำหรับผู้หักภาษี ณ ที่จ่าย เก็บไว้เป็นหลักฐาน)'
] 
%}

{% for i in range(4) %}

<div class="page-break">
    <div class="o_report_withholding_tax_cert" colspan="4">
        {% if doc.docstatus == 2 %}
            <div class="watermark">ยกเลิก</div>
        {% endif %}
        {% if doc.amended_from %}
            <div class="amended_from_label">ออกแทนเอกสารเลขที่</div>
            <div class="amended_from">{{ doc.amended_from }}</div>
        {% endif %}

        <div class="signature" >
            {% if print_actions["signed"]["signature"] %}
                <img class="action-signature-image" src="{{ print_actions["signed"]["signature"] | e }}" alt="">
            {% else %}
                <span class="signature-placeholder" aria-hidden="true"></span>
            {% endif %}
            <div class="signature-name">{{ print_actions["signed"]["name"] }}</div>
            <div class="signature-role">(ผู้หักภาษี ณ ที่จ่าย)</div>
        </div>
        <div class="sign_date" >
            {% if print_actions["signed"]["acted_at"] %}
                {{ format_date(print_actions["signed"]["acted_at"]) }}
            {% endif %}
            <div class="sign_date_caption">วันที่</div>
        </div>
        <div class="copy" >
            {{ copies[i] }}
        </div>
        <div class="number">
            {{ doc.name }}
        </div>
        <div class="number_payment">
            {{ doc.voucher_no }}
        </div>
        {% if doc.company_tax_id %}
        <div class="company_vat">
            <div class="company_vat_1">
                {{ doc.company_tax_id[:1] }}
            </div>
            <div class="company_vat_2">
                {{ doc.company_tax_id[1:2] }}
            </div>
            <div class="company_vat_3">
                {{ doc.company_tax_id[2:3] }}
            </div>
            <div class="company_vat_4">
                {{ doc.company_tax_id[3:4] }}
            </div>
            <div class="company_vat_5">
                {{ doc.company_tax_id[4:5] }}
            </div>
            <div class="company_vat_6">
                {{ doc.company_tax_id[5:6] }}
            </div>
            <div class="company_vat_7">
                {{ doc.company_tax_id[6:7] }}
            </div>
            <div class="company_vat_8">
                {{ doc.company_tax_id[7:8] }}
            </div>
            <div class="company_vat_9">
                {{ doc.company_tax_id[8:9] }}
            </div>
            <div class="company_vat_10">
                {{ doc.company_tax_id[9:10] }}
            </div>
            <div class="company_vat_11">
                {{ doc.company_tax_id[10:11] }}
            </div>
            <div class="company_vat_12">
                {{ doc.company_tax_id[11:12] }}
            </div>
            <div class="company_vat_13">
                {{ doc.company_tax_id[12:13] }}
            </div>
        </div>
        {%- endif -%}
        <div class="company_name">
            <p>
                {{ doc.company }}
            </p>
        </div>
        {% set company_address = [] %}
        {% set a = frappe.get_doc("Address", doc.company_address) %}
        {% for name in [a.address_line1, a.address_line2, a.city, a.county, a.state, a.pincode] %}
        {%   if name != None %}
        {{     company_address.append(name) or '' }}
        {%   endif %} 
        {% endfor %}
        <div class="company_address" colspan="4">
            {{ company_address|join(", ") }}
        </div>
        {% set sup = frappe.get_doc("Supplier", doc.supplier) %}
        {% if sup.tax_id %}
        <div class="supplier_vat">
            <div class="supplier_vat_1">
                {{ sup.tax_id[:1] }}
            </div>
            <div class="supplier_vat_2">
                {{ sup.tax_id[1:2] }}
            </div>
            <div class="supplier_vat_3">
                {{ sup.tax_id[2:3] }}
            </div>
            <div class="supplier_vat_4">
                {{ sup.tax_id[3:4] }}
            </div>
            <div class="supplier_vat_5">
                {{ sup.tax_id[4:5] }}
            </div>
            <div class="supplier_vat_6">
                {{ sup.tax_id[5:6] }}
            </div>
            <div class="supplier_vat_7">
                {{ sup.tax_id[6:7] }}
            </div>
            <div class="supplier_vat_8">
                {{ sup.tax_id[7:8] }}
            </div>
            <div class="supplier_vat_9">
                {{ sup.tax_id[8:9] }}
            </div>
            <div class="supplier_vat_10">
                {{ sup.tax_id[9:10] }}
            </div>
            <div class="supplier_vat_11">
                {{ sup.tax_id[10:11] }}
            </div>
            <div class="supplier_vat_12">
                {{ sup.tax_id[11:12] }}
            </div>
            <div class="supplier_vat_13">
                {{ sup.tax_id[12:13] }}
            </div>
        </div>
        {%- endif -%}
        <div class="supplier_name">
            <p> 
                {% if doc.is_agent and doc.withholding_agent_for_name %}
                    {{ sup.supplier_name }}  กระทำแทนโดย {{ doc.withholding_agent_for_name }} 
                {% else %} 
                    {{ sup.supplier_name }} 
                {% endif %} 
            </p>
        </div>
        {% set supplier_address = [] %}
        {% set a = frappe.get_doc("Address", doc.supplier_address) %}
        {% for name in [a.address_line1, a.address_line2, a.city, a.county, a.state, a.pincode] %}
        {%   if name != None %}
        {{     supplier_address.append(name) or ''}}
        {%   endif %} 
        {% endfor%} 
        <div class="supplier_address">
            {{ supplier_address|join(", ") }}
        </div>
        <div class="income_tax_form">
        {% if doc.income_tax_form == 'PND1' %}
            <div class="choice_pnd1a">X</div>
        {% endif %} 
        {% if doc.income_tax_form == 'PND3' %}
            <div class="choice_pnd3">X</div>
        {% endif %} 
        {% if doc.income_tax_form == 'PND3a' %}
            <div class="choice_pnd3a">X</div>
        {% endif %} 
        {% if doc.income_tax_form == 'PND53' %}
            <div class="choice_pnd53">X</div>
        {% endif %} 
        </div>
        <div class="wht_items">
        {% for item in doc.withholding_tax_items | selectattr('type_of_income') %}
        {%   set type = item.type_of_income|replace('.', '') %}
        {%   if type == '6' %}
        <div class="type_{{ type }}_desc">
            {{ item.description }}
        </div>
        {%   endif %}
        <div class="type_{{ type }}_date">
            {{ format_date(doc.date) or "-" }}
        </div>
        <div class="type_{{ type }}_base">
            {{ "{:,.2f}".format(item.tax_base) }}
        </div>
        <div class="type_{{ type }}_tax">
            {{ "{:,.2f}".format(item.tax_amount) }}
        </div>
        {% endfor %}
        </div>
        <div class="total_base">
            {{ "{:,.2f}".format(doc.withholding_tax_items | sum(attribute='tax_base')) }}
        </div>
        <div class="total_tax">
            {{ "{:,.2f}".format(doc.withholding_tax_items | sum(attribute='tax_amount')) }}
        </div>
        <div class="amount_in_words">
            {{ amount_in_bahttext(doc.withholding_tax_items | sum(attribute='tax_amount')) }}
        </div>
        <div class="tax_payer">
        {% if doc.tax_payer == 'Withholding' %}
            <div class="tax_payer_withholding">X</div>
        {% endif %} 
        {% if doc.tax_payer == 'Paid One Time' %}
            <div class="tax_payer_paid_one_time">X</div>
        {% endif %}
        </div>
    </div>
</div>

{% endfor %}
